import{_ as o,r as s,o as p,c,e as a,a as i,s as l}from"./chunks/framework.CXcwiNg-.js";const y=JSON.parse('{"title":"Building Components - October CMS - 2.x","titleTemplate":false,"description":"","frontmatter":{},"headers":[{"level":2,"title":"Component Class Definition","slug":"component-class-definition","link":"#component-class-definition","children":[{"level":3,"title":"Component Registration","slug":"component-registration","link":"#component-registration","children":[]}]},{"level":2,"title":"Component Properties","slug":"component-properties","link":"#component-properties","children":[{"level":3,"title":"Dropdown and Set Properties","slug":"dropdown-and-set-properties","link":"#dropdown-and-set-properties","children":[]},{"level":3,"title":"Page List Properties","slug":"page-list-properties","link":"#page-list-properties","children":[]}]},{"level":2,"title":"Routing Parameters","slug":"routing-parameters","link":"#routing-parameters","children":[]},{"level":2,"title":"Handling the Page Execution Cycle","slug":"handling-the-page-execution-cycle","link":"#handling-the-page-execution-cycle","children":[{"level":3,"title":"Page Execution Life Cycle Handlers","slug":"page-execution-life-cycle-handlers","link":"#page-execution-life-cycle-handlers","children":[]},{"level":3,"title":"Component Initialization","slug":"component-initialization","link":"#component-initialization","children":[]},{"level":3,"title":"Halting With a Response","slug":"halting-with-a-response","link":"#halting-with-a-response","children":[]}]},{"level":2,"title":"AJAX Handlers","slug":"ajax-handlers","link":"#ajax-handlers","children":[]},{"level":2,"title":"Default Markup","slug":"default-markup","link":"#default-markup","children":[]},{"level":2,"title":"Component Partials","slug":"component-partials","link":"#component-partials","children":[{"level":3,"title":"Referencing \\"self\\"","slug":"referencing-self","link":"#referencing-self","children":[]},{"level":3,"title":"Unique Identifier","slug":"unique-identifier","link":"#unique-identifier","children":[]}]},{"level":2,"title":"Rendering Partials from Code","slug":"rendering-partials-from-code","link":"#rendering-partials-from-code","children":[]},{"level":2,"title":"Injecting Page Assets with Components","slug":"injecting-page-assets-with-components","link":"#injecting-page-assets-with-components","children":[]}],"relativePath":"2.x/plugin/components.md","filePath":"2.x/plugin/components.md"}'),r={name:"2.x/plugin/components.md"};function u(d,n,g,k,h,m){const t=s("pre-heading"),e=s("post-heading");return p(),c("div",null,[a(t),n[0]||(n[0]=i("h1",null,"Building Components",-1)),a(e),n[1]||(n[1]=l(`<p>Components files and directories reside in the <strong>components</strong> subdirectory of a plugin directory. Each component has a PHP file defining the component class and an optional component partials directory. The component partials directory name matches the component class name written in lowercase. An example of a component directory structure:</p><pre class="dir-container"><code><p>├── plugins
|   └── acme
|       └── blog
|           ├── <code>components</code>
|           |   ├── blogposts       <em>&lt;== Partials Directory</em>
|           |   |   └── default.htm <em>&lt;== Default Markup (Optional)</em>
|           |   └── BlogPosts.php   <em>&lt;== Component Class</em>
|           └── Plugin.php</p>
</code></pre><p>Components must be <a href="#oc-component-registration">registered in the Plugin registration class</a> with the <code>registerComponents</code> method.</p><p><a id="oc-component-class-definition"></a></p><h2 id="component-class-definition"><a href="#component-class-definition" class="header-anchor">#</a> Component Class Definition</h2><p>The <strong>component class file</strong> defines the component functionality and <a href="#oc-component-properties">component properties</a>. The component class file name should match the component class name. Component classes should extend the <code>\\Cms\\Classes\\ComponentBase</code> class. The component from the next example should be defined in the plugins/acme/blog/components/BlogPosts.php file.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">namespace</span> <span class="token package">Acme<span class="token punctuation">\\</span>Blog<span class="token punctuation">\\</span>Components</span><span class="token punctuation">;</span>

<span class="token keyword">class</span> <span class="token class-name-definition class-name">BlogPosts</span> <span class="token keyword">extends</span> <span class="token class-name class-name-fully-qualified"><span class="token punctuation">\\</span>Cms<span class="token punctuation">\\</span>Classes<span class="token punctuation">\\</span>ComponentBase</span>
<span class="token punctuation">{</span>
    <span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">componentDetails</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
    <span class="token punctuation">{</span>
        <span class="token keyword">return</span> <span class="token punctuation">[</span>
            <span class="token string single-quoted-string">&#39;name&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Blog Posts&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;description&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Displays a collection of blog posts.&#39;</span>
        <span class="token punctuation">]</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>

    <span class="token comment">/**
     * posts becomes available on the page as {{ component.posts }}
     */</span>
    <span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">posts</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
    <span class="token punctuation">{</span>
        <span class="token keyword">return</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;First Post&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;Second Post&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;Third Post&#39;</span><span class="token punctuation">]</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre></div><p>The <code>componentDetails</code> method is required. The method should return an array with two keys: <code>name</code> and <code>description</code>. The name and description are display in the CMS back-end user interface.</p><p>When this <a href="./../cms/components.html">component is attached to a page or layout</a>, the class properties and methods become available on the page through the component variable, which name matches the component short name or the alias. For example, if the BlogPost component from the previous example was defined on a page with its short name:</p><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token key attr-name">url</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">/blog</span>&quot;</span>

<span class="token section"><span class="token punctuation">[</span><span class="token section-name selector">blogPosts</span><span class="token punctuation">]</span></span>
<span class="token punctuation">=</span><span class="token value attr-value">=</span>
</code></pre></div><p>You would be able to access its <code>posts</code> method through the <code>blogPosts</code> variable. Note that Twig supports the property notation for methods, so that you don&#39;t need to use brackets.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">for</span> post <span class="token operator">in</span> blogPosts<span class="token punctuation">.</span>posts <span class="token delimiter punctuation">%}</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> post <span class="token delimiter punctuation">}}</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endfor</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p><a id="oc-component-registration"></a></p><h3 id="component-registration"><a href="#component-registration" class="header-anchor">#</a> Component Registration</h3><p>Components must be registered by overriding the <code>registerComponents</code> method inside the <a href="./registration.html#oc-registration-file">Plugin registration class</a>. This tells the CMS about the Component and provides a <strong>short name</strong> for using it. An example of registering a component:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">registerComponents</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token punctuation">[</span>
        <span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>October<span class="token punctuation">\\</span>Demo<span class="token punctuation">\\</span>Components<span class="token punctuation">\\</span>Todo</span><span class="token operator">::</span><span class="token keyword">class</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;demoTodo&#39;</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>This will register the Todo component class with the default alias name <strong>demoTodo</strong>. More information on using components can be found at the <a href="./../cms/components.html">CMS components article</a>.</p><p><a id="oc-component-properties"></a></p><h2 id="component-properties"><a href="#component-properties" class="header-anchor">#</a> Component Properties</h2><p>When you add a component to a page or layout you can configure it using properties. The properties are defined with the <code>defineProperties</code> method of the component class. The next example shows how to define a component property:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">defineProperties</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;maxItems&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
            <span class="token string single-quoted-string">&#39;title&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Max items&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;description&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;The most amount of todo items allowed&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;default&#39;</span> <span class="token operator">=&gt;</span> <span class="token number">10</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;type&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;string&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;validationPattern&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;^[0-9]+$&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;validationMessage&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;The Max Items property can contain only numeric symbols&#39;</span>
        <span class="token punctuation">]</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>The method should return an array with the property keys as indexes and property parameters as values. The property keys are used for accessing the component property values inside the component class. The property parameters are defined with an array with the following keys:</p><div class="table"><table tabindex="0"><thead><tr><th>Key</th><th>Description</th></tr></thead><tbody><tr><td><strong>title</strong></td><td>required, the property title, it is used by the component Inspector in the CMS back-end.</td></tr><tr><td><strong>description</strong></td><td>required, the property description, it is used by the component Inspector in the CMS back-end.</td></tr><tr><td><strong>default</strong></td><td>optional, the default property value to use when the component is added to a page or layout in the CMS back-end.</td></tr><tr><td><strong>type</strong></td><td>optional, specifies the property type. The type defines the way how the property is displayed in the Inspector. Currently supported types are <strong>string</strong>, <strong>checkbox</strong>, <strong>dropdown</strong> and <strong>set</strong>. Default value: <strong>string</strong>.</td></tr><tr><td><strong>validationPattern</strong></td><td>optional Regular Expression to use when a user enters the property value in the Inspector. The validation can be used only with <strong>string</strong> properties.</td></tr><tr><td><strong>validationMessage</strong></td><td>optional error message to display if the validation fails.</td></tr><tr><td><strong>required</strong></td><td>optional, forces field to be filled. Uses validationMessage when left empty.</td></tr><tr><td><strong>placeholder</strong></td><td>optional placeholder for string and dropdown properties.</td></tr><tr><td><strong>options</strong></td><td>optional array of options for dropdown properties.</td></tr><tr><td><strong>depends</strong></td><td>an array of property names a dropdown property depends on. See the <a href="#oc-dropdown-and-set-properties">dropdown properties</a> below.</td></tr><tr><td><strong>group</strong></td><td>an optional group name. Groups create sections in the Inspector simplifying the user experience. Use a same group name in multiple properties to combine them.</td></tr><tr><td><strong>showExternalParam</strong></td><td>specifies visibility of the External Parameter editor for the property in the Inspector. Default value: <strong>true</strong>.</td></tr></tbody></table></div><p>Inside the component you can read the property value with the <code>property</code> method:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">property</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;maxItems&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>If the property value is not defined, you can supply the default value as a second parameter of the <code>property</code> method:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">property</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;maxItems&#39;</span><span class="token punctuation">,</span> <span class="token number">6</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>You can also load all the properties as array:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$properties</span> <span class="token operator">=</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">getProperties</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>To access the property from the Twig partials for the component, utilize the <code>__SELF__</code> variable which refers to the Component object:</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> __SELF__<span class="token punctuation">.</span>property<span class="token punctuation">(</span><span class="token string"><span class="token punctuation">&#39;</span>maxItems<span class="token punctuation">&#39;</span></span><span class="token punctuation">)</span> <span class="token delimiter punctuation">}}</span></span>
</code></pre></div><p><a id="oc-dropdown-and-set-properties"></a></p><h3 id="dropdown-and-set-properties"><a href="#dropdown-and-set-properties" class="header-anchor">#</a> Dropdown and Set Properties</h3><p>The option list for dropdown and set properties can be static or dynamic. Static options are defined with the <code>options</code> element of the property definition. Example:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">defineProperties</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;units&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
            <span class="token string single-quoted-string">&#39;title&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Units&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;type&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;dropdown&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;default&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;imperial&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;placeholder&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Select units&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;options&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;metric&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Metric&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;imperial&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Imperial&#39;</span><span class="token punctuation">]</span>
        <span class="token punctuation">]</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>The list of options could be fetched dynamically from the server when the Inspector is displayed. If the <code>options</code> parameter is omitted in a dropdown or set property definition the option list is considered dynamic. The component class must define a method returning the option list. The method should have a name in the following format: <code>get*Property*Options</code>, where <strong>Property</strong> is the property name, for example: <code>getCountryOptions</code>. The method returns an array of options with the option values as keys and option labels as values. Example of a dynamic dropdown list definition:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">defineProperties</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;country&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
            <span class="token string single-quoted-string">&#39;title&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Country&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;type&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;dropdown&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;default&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;us&#39;</span>
        <span class="token punctuation">]</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>

<span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">getCountryOptions</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;us&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;United states&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;ca&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Canada&#39;</span><span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>Dynamic dropdown and set lists can depend on other properties. For example, the state list could depend on the selected country. The dependencies are declared with the <code>depends</code> parameter in the property definition. The next example defines two dynamic dropdown properties and the state list depends on the country:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">defineProperties</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;country&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
            <span class="token string single-quoted-string">&#39;title&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Country&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;type&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;dropdown&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;default&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;us&#39;</span>
        <span class="token punctuation">]</span><span class="token punctuation">,</span>
        <span class="token string single-quoted-string">&#39;state&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
            <span class="token string single-quoted-string">&#39;title&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;State&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;type&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;dropdown&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;default&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;dc&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;depends&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;country&#39;</span><span class="token punctuation">]</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;placeholder&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Select a state&#39;</span>
        <span class="token punctuation">]</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>In order to load the state list you should know what country is currently selected in the Inspector. The Inspector POSTs all property values to the <code>getPropertyOptions</code> handler, so you can do the following:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">getStateOptions</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token comment">// Load the country property value from POST</span>
    <span class="token variable">$countryCode</span> <span class="token operator">=</span> <span class="token function">post</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;country&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

    <span class="token variable">$states</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;ca&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;ab&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Alberta&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;bc&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;British columbia&#39;</span><span class="token punctuation">]</span><span class="token punctuation">,</span>
        <span class="token string single-quoted-string">&#39;us&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;al&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Alabama&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;ak&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Alaska&#39;</span><span class="token punctuation">]</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>

    <span class="token keyword">return</span> <span class="token variable">$states</span><span class="token punctuation">[</span><span class="token variable">$countryCode</span><span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h3 id="page-list-properties"><a href="#page-list-properties" class="header-anchor">#</a> Page List Properties</h3><p>Sometimes components need to create links to the website pages. For example, the blog post list contains links to the blog post details page. In this case the component should know the post details page file name (then it can use the <a href="./../markup/filter-page.html">page Twig filter</a>). October includes a helper for creating dynamic dropdown page lists. The next example defines the postPage property which displays a list of pages:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">defineProperties</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
        <span class="token keyword">return</span> <span class="token punctuation">[</span>
            <span class="token string single-quoted-string">&#39;postPage&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
                <span class="token string single-quoted-string">&#39;title&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Post page&#39;</span><span class="token punctuation">,</span>
                <span class="token string single-quoted-string">&#39;type&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;dropdown&#39;</span><span class="token punctuation">,</span>
                <span class="token string single-quoted-string">&#39;default&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;blog/post&#39;</span>
            <span class="token punctuation">]</span>
        <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>

<span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">getPostPageOptions</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token class-name static-context">Page</span><span class="token operator">::</span><span class="token function">sortBy</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;baseFileName&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">lists</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;baseFileName&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;baseFileName&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h2 id="routing-parameters"><a href="#routing-parameters" class="header-anchor">#</a> Routing Parameters</h2><p>Components can directly access routing parameter values defined in the <a href="./../cms/pages.html#oc-url-syntax">URL of the page</a>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token comment">// Returns the URL segment value, eg: /page/:post_id</span>
<span class="token variable">$postId</span> <span class="token operator">=</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">param</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;post_id&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>In some cases a <a href="#oc-component-properties">component property</a> may act as a hard coded value or reference the value from the URL.</p><p>This hard coded example shows the blog post with an identifier <code>2</code> being used:</p><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token key attr-name">url</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">/blog/hard-coded-page</span>&quot;</span>

<span class="token section"><span class="token punctuation">[</span><span class="token section-name selector">blogPost</span><span class="token punctuation">]</span></span>
<span class="token key attr-name">id</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">2</span>&quot;</span>
</code></pre></div><p>Alternatively the value can be referenced dynamically from the page URL using an <a href="./../cms/components.html#oc-using-external-property-values">external property value</a>:</p><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token key attr-name">url</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">/blog/:my_custom_parameter</span>&quot;</span>

<span class="token section"><span class="token punctuation">[</span><span class="token section-name selector">blogPost</span><span class="token punctuation">]</span></span>
<span class="token key attr-name">id</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">{{ :my_custom_parameter }}</span>&quot;</span>
</code></pre></div><p>In both cases the value can be retrieved by using the <code>property</code> method:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">property</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;id&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>If you need to access the routing parameter name:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token comment">// Returns &quot;my_custom_parameter&quot;</span>
<span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">paramName</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;id&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p><a id="oc-handling-the-page-execution-cycle"></a></p><h2 id="handling-the-page-execution-cycle"><a href="#handling-the-page-execution-cycle" class="header-anchor">#</a> Handling the Page Execution Cycle</h2><p>Components can be involved in the Page execution cycle events by overriding the <code>onRun</code> method in the component class. The CMS controller executes this method every time when the page or layout loads. Inside the method you can inject variables to the Twig environment through the <code>page</code> property:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">onRun</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token comment">// This code will be executed when the page or layout is</span>
    <span class="token comment">// loaded and the component is attached to it.</span>

    <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token property">page</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;var&#39;</span><span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;value&#39;</span><span class="token punctuation">;</span> <span class="token comment">// Inject some variable to the page</span>
<span class="token punctuation">}</span>
</code></pre></div><h3 id="page-execution-life-cycle-handlers"><a href="#page-execution-life-cycle-handlers" class="header-anchor">#</a> Page Execution Life Cycle Handlers</h3><p>When a page loads, October executes handler functions that could be defined in the layout and page <a href="./../cms/themes.html#oc-php-section">PHP section</a> and component classes. The sequence the handlers are executed is following:</p><ol><li>Layout <code>onInit()</code> function.</li><li>Page <code>onInit()</code> function.</li><li>Layout <code>onStart()</code> function.</li><li>Layout components <code>onRun()</code> method.</li><li>Layout <code>onBeforePageStart()</code> function.</li><li>Page <code>onStart()</code> function.</li><li>Page components <code>onRun()</code> method.</li><li>Page <code>onEnd()</code> function.</li><li>Layout <code>onEnd()</code> function.</li></ol><p><a id="oc-component-initialization"></a></p><h3 id="component-initialization"><a href="#component-initialization" class="header-anchor">#</a> Component Initialization</h3><p>Sometimes you may wish to execute code at the time the component class is first instantiated. You may override the <code>init</code> method in the component class to handle any initialization logic, this will execute before AJAX handlers and before the page execution life cycle. For example, this method can be used for attaching another component to the page dynamically.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">init</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">addComponent</span><span class="token punctuation">(</span><span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>Acme<span class="token punctuation">\\</span>Blog<span class="token punctuation">\\</span>Components<span class="token punctuation">\\</span>BlogPosts</span><span class="token operator">::</span><span class="token keyword">class</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;blogPosts&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h3 id="halting-with-a-response"><a href="#halting-with-a-response" class="header-anchor">#</a> Halting With a Response</h3><p>Like all methods in the <a href="./../cms/layouts.html#oc-dynamic-layouts">page execution life cycle</a>, if the <code>onRun</code> method in a component returns a value, this will stop the cycle at this point and return the response to the browser. Here we return an access denied message using the <code>Response</code> facade:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">onRun</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token constant boolean">true</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token keyword">return</span> <span class="token class-name static-context">Response</span><span class="token operator">::</span><span class="token function">make</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;Access denied!&#39;</span><span class="token punctuation">,</span> <span class="token number">403</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre></div><p>You can also return a 404 response from the <code>onRun</code> method:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">onRun</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token constant boolean">true</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">setStatusCode</span><span class="token punctuation">(</span><span class="token number">404</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
        <span class="token keyword">return</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token property">controller</span><span class="token operator">-&gt;</span><span class="token function">run</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;404&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre></div><p><a id="oc-ajax-handlers"></a></p><h2 id="ajax-handlers"><a href="#ajax-handlers" class="header-anchor">#</a> AJAX Handlers</h2><p>Components can host AJAX event handlers. They are defined in the component class exactly like they can be defined in the <a href="./../ajax/handlers.html">page or layout code</a>. An example AJAX handler method defined in a component class:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">onAddItem</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token variable">$value1</span> <span class="token operator">=</span> <span class="token function">post</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;value1&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token variable">$value2</span> <span class="token operator">=</span> <span class="token function">post</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;value2&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token property">page</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;result&#39;</span><span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token variable">$value1</span> <span class="token operator">+</span> <span class="token variable">$value2</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>If the alias for this component was <em>demoTodo</em> this handler can be accessed by <code>demoTodo::onAddItem</code>. Please see the <a href="./../ajax/handlers.html#oc-calling-a-handler">Calling AJAX handlers defined in components</a> article for details about using AJAX with components.</p><h2 id="default-markup"><a href="#default-markup" class="header-anchor">#</a> Default Markup</h2><p>All components can come with default markup that is used when including it on a page with the <code>{% component %}</code> tag, although this is optional. Default markup is kept inside the <strong>component partials directory</strong>, which has the same name as the component class in lower case.</p><p>The default component markup should be placed in a file named <strong>default.htm</strong>. For example, the default markup for the Demo ToDo component is defined in the file <strong>/plugins/october/demo/components/todo/default.htm</strong>. It can then be inserted anywhere on the page by using the <code>{% component %}</code> tag:</p><div class="language- extra-class"><pre class="language-text"><code>url = &quot;/todo&quot;

[demoTodo]
==
{% component &#39;demoTodo&#39; %}
</code></pre></div><p>The default markup can also take parameters that override the <a href="#oc-component-properties">component properties</a> at the time they are rendered.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">component</span> <span class="token string"><span class="token punctuation">&#39;</span>demoTodo<span class="token punctuation">&#39;</span></span> maxItems<span class="token operator">=</span><span class="token string"><span class="token punctuation">&quot;</span>7<span class="token punctuation">&quot;</span></span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>These properties will not be available in the <code>onRun</code> method since they are established after the page cycle has completed. Instead they can be processed by overriding the <code>onRender</code> method in the component class. The CMS controller executes this method before the default markup is rendered.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">onRender</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token comment">// This code will be executed before the default component</span>
    <span class="token comment">// markup is rendered on the page or layout.</span>

    <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token property">page</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;var&#39;</span><span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;Maximum items allowed: &#39;</span> <span class="token operator">.</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">property</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;maxItems&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p><a id="oc-component-partials"></a></p><h2 id="component-partials"><a href="#component-partials" class="header-anchor">#</a> Component Partials</h2><p>In addition to the default markup, components can also offer additional partials that can be used on the front-end or within the default markup itself. If the Demo ToDo component had a <strong>pagination</strong> partial, it would be located in <strong>/plugins/october/demo/components/todo/pagination.htm</strong> and displayed on the page using:</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">partial</span> <span class="token string"><span class="token punctuation">&#39;</span>demoTodo::pagination<span class="token punctuation">&#39;</span></span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>A relaxed method can be used that is contextual. If called inside a component partial, it will directly refer to itself. If called inside a theme partial, it will scan all components used on the page/layout for a matching partial name and use that.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">partial</span> <span class="token string"><span class="token punctuation">&#39;</span>@pagination<span class="token punctuation">&#39;</span></span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>Multiple components can share partials by placing the partial file in a directory called <strong>components/partials</strong>. The partials found in this directory are used as a fallback when the usual component partial cannot be found. For example, a shared partial located in <strong>/plugins/acme/blog/components/partials/shared.htm</strong> can be displayed on the page by any component using:</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">partial</span> <span class="token string"><span class="token punctuation">&#39;</span>@shared<span class="token punctuation">&#39;</span></span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><h3 id="referencing-self"><a href="#referencing-self" class="header-anchor">#</a> Referencing &quot;self&quot;</h3><p>Components can reference themselves inside their partials by using the <code>__SELF__</code> variable. By default it will return the component&#39;s short name or <a href="./../cms/components.html#oc-components-aliases">alias</a>.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>form</span> <span class="token attr-name">data-request</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span>__SELF__<span class="token delimiter punctuation">}}</span></span>::onEventHandler<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
    [...]
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>form</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>Components can also reference their own properties.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">for</span> item <span class="token operator">in</span> __SELF__<span class="token punctuation">.</span>items<span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token delimiter punctuation">%}</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> item <span class="token delimiter punctuation">}}</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endfor</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>If inside a component partial you need to render another component partial concatenate the <code>__SELF__</code> variable with the partial name:</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">partial</span> __SELF__<span class="token operator">~</span><span class="token string"><span class="token punctuation">&quot;</span>::screenshot-list<span class="token punctuation">&quot;</span></span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><h3 id="unique-identifier"><a href="#unique-identifier" class="header-anchor">#</a> Unique Identifier</h3><p>If an identical component is called twice on the same page, an <code>id</code> property can be used to reference each instance.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span>__SELF__<span class="token punctuation">.</span>id<span class="token delimiter punctuation">}}</span></span>
</code></pre></div><p>The ID is unique each time the component is displayed.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token comment">&lt;!-- ID: demoTodo527c532e9161b --&gt;</span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">component</span> <span class="token string"><span class="token punctuation">&#39;</span>demoTodo<span class="token punctuation">&#39;</span></span> <span class="token delimiter punctuation">%}</span></span>

<span class="token comment">&lt;!-- ID: demoTodo527c532ec4c33 --&gt;</span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">component</span> <span class="token string"><span class="token punctuation">&#39;</span>demoTodo<span class="token punctuation">&#39;</span></span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><h2 id="rendering-partials-from-code"><a href="#rendering-partials-from-code" class="header-anchor">#</a> Rendering Partials from Code</h2><p>You may programmatically render component partials inside the PHP code using the <code>renderPartial</code> method. This will check the component for the partial named <code>component-partial.htm</code> and return the result as a string. The second parameter is used for passing view variables. The same <a href="#oc-component-partials">path resolution logic</a> applies when you render a component partial in PHP as it does with Twig; use the <code>@</code> prefix to refer to partials within the component itself.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$content</span> <span class="token operator">=</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">renderPartial</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;@component-partial.htm&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token variable">$content</span> <span class="token operator">=</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">renderPartial</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;@component-partial.htm&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">[</span>
    <span class="token string single-quoted-string">&#39;name&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;John Smith&#39;</span>
<span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>For example, to render a partial as a response to an <a href="./../ajax/handlers.html">AJAX handler</a>:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">function</span> <span class="token function-definition function">onGetTemplate</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;#someDiv&#39;</span> <span class="token operator">=&gt;</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">renderPartial</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;@component-partial.htm&#39;</span><span class="token punctuation">)</span><span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>Another example could be overriding the entire page view response by returning a value from the <code>onRun</code> <a href="#oc-handling-the-page-execution-cycle">page cycle method</a>. This code will specifically return an XML response using the <code>Response</code> facade:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">onRun</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token variable">$content</span> <span class="token operator">=</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">renderPartial</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;@default.htm&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token keyword">return</span> <span class="token class-name static-context">Response</span><span class="token operator">::</span><span class="token function">make</span><span class="token punctuation">(</span><span class="token variable">$content</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">header</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;Content-Type&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;text/xml&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p><a id="oc-injecting-page-assets-with-components"></a></p><h2 id="injecting-page-assets-with-components"><a href="#injecting-page-assets-with-components" class="header-anchor">#</a> Injecting Page Assets with Components</h2><p>Components can inject assets (CSS and JavaScript files) to pages or layouts they&#39;re attached to. Use the controller&#39;s <code>addCss</code> and <code>addJs</code> methods to add assets to the CMS controllers. It could be done in the component&#39;s <code>onRun</code> method. Please read more details about <a href="./../cms/pages.html#oc-injecting-page-assets-programmatically">injecting assets in the Pages article</a>. Example:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">onRun</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">addJs</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;/plugins/acme/blog/assets/javascript/blog-controls.js&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>If the path specified in the <code>addCss</code> and <code>addJs</code> method argument begins with a slash (/) then it will be relative to the website root. If the asset path does not begin with a slash then it is relative to the component directory.</p><p>The <code>addCss</code> and <code>addJs</code> methods provide a second argument that defines the attributes of your injected asset as an array. A special attribute - <code>build</code> - is available, that will suffix your injected assets with the current version of the plugin specified. This can be used to refresh cached assets when a plugin is upgraded.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">onRun</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">addJs</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;/plugins/acme/blog/assets/javascript/blog-controls.js&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;build&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Acme.Test&#39;</span><span class="token punctuation">,</span>
        <span class="token string single-quoted-string">&#39;defer&#39;</span> <span class="token operator">=&gt;</span> <span class="token constant boolean">true</span>
    <span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>You may also use a string as the second argument, which then defaults to using the string value as the <code>build</code>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">onRun</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">addJs</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;/plugins/acme/blog/assets/javascript/blog-controls.js&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;Acme.Test&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div>`,121))])}const w=o(r,[["render",u]]);export{y as __pageData,w as default};
